        assertEquals("CONFIRMED", c.get("status").asText());
        assertEquals("779.80", c.get("amountPaid").asText());
        assertError(call("POST", "/reservations/" + id + "/confirmation", null), 409, "OPERATION_NOT_ALLOWED");

