        assertEquals("text/csv; charset=utf-8", occ.headers().firstValue("Content-Type").orElse(""));
        assertEquals("room,type,reservation,check_in,check_out\n301,SUITE," + a + ",2032-07-10,2032-07-12\ntotal,1/5\n", occ.body());
